<script setup>
import GettingStarted from '../GettingStarted.vue'
import {ref,onMounted} from 'vue'
import {request} from './client'
import {object} from './contracts'
import Subscription from './Subscription.vue'
import FinanceOperations from './FinanceOperations.vue'
import OwnerAccess from './OwnerAccess.vue'
import PlanEditor from './PlanEditor.vue'
const auditRows=ref([]),auditPage=ref(0),manifest=ref(null)
import './release.css'
const page=ref(0),spec=ref(null),monthlyPrice=ref(0),priceEnabled=ref(true),commercial=ref(null)
const tab=ref('Organizations'),data=ref(null),busy=ref(false),error=ref(''),note=ref(''),reason=ref(''),tenant=ref(''),domain=ref(''),override=ref('{"features":{},"limits":{},"support_tier":"standard"}'),state=ref('past_due'),grace=ref(''),days=ref(7),edit=ref(null),health=ref(null)
const form=ref({title:'',code:'',site_hostname:'',admin_contact:'',plan:'STARTER'})
async function run(fn){if(busy.value)return;busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await request('release','control_room',{page:page.value},'GET')}
async function action(method,args){await run(async()=>{const result=await request('platform',method,args);manifest.value=null;note.value=method==='register'?'Institute setup request saved. Continue in Provisioning; the institute website is not active yet.':result.queued?'Invitation queued. Inbox delivery has not been confirmed.':result.requires_manifest_delivery?'Saved. Operator must deliver a new signed manifest to the tenant.':'Saved to the control plane.';await load()})}
async function choose(o){manifest.value=null;commercial.value=null;tenant.value=o.name;domain.value=o.custom_domain||'';override.value=JSON.stringify(object(o.subscription?.overrides),null,2);await run(async()=>{commercial.value=await request('premium','summary',{tenant:o.name},'GET');monthlyPrice.value=commercial.value.offer?.amount_minor||0})}
function editPlan(p){edit.value={plan:p.name,features:object(p.features),limits:object(p.limits),price_minor:p.price_minor,period_days:p.period_days}}
async function savePlan(){await run(async()=>{await request('platform','configure_plan',{...edit.value,reason:reason.value});await load();note.value='Plan revision saved. Existing signed subscriptions and quotes are unchanged.'})}
async function loadAudit(){auditRows.value=await request('platform','audit_log',{page:auditPage.value},'GET')}
async function selectTab(name){tab.value=name;if(name==='Audit log')await run(loadAudit)}
async function saveOverrides(){await run(async()=>{const values=JSON.parse(override.value);await request('platform','override',{tenant:tenant.value,values,reason:reason.value});manifest.value=null;await load();note.value='Overrides saved. Deliver a new signed policy to apply them on the institute site.'})}
async function saveOffer(){await run(async()=>{await request('premium','configure_offer',{tenant:tenant.value,amount_minor:monthlyPrice.value,enabled:priceEnabled.value,reason:reason.value});commercial.value=await request('premium','summary',{tenant:tenant.value},'GET');note.value='Monthly offer saved. Payments remain subject to the existing pause; no charge or activation occurred.'})}
async function exportManifest(){await run(async()=>{manifest.value=await request('platform','manifest',{tenant:tenant.value});note.value='Signed policy generated. Download and deliver it using the institute operator workflow; it has not been applied remotely.'})}
function downloadManifest(){const url=URL.createObjectURL(new Blob([JSON.stringify(manifest.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sisu-policy-'+tenant.value+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>run(load))
</script>
<template><main class="release"><h1>SISU administration</h1><p>Manage your institutes, subscriptions and platform setup.</p><a href="/api/method/logout">Sign out</a><GettingStarted v-if="tab==='Platform guide'" role="Super Admin"/><nav aria-label="Platform sections"><button v-for="name in ['Organizations','Plans','Site policies','Provisioning','Billing','Commerce','Admin access','Audit log','Readiness','Platform guide']" :key="name" class="button subtle" :aria-pressed="tab===name" @click="selectTab(name)" :disabled="busy">{{name}}</button></nav><p v-if="busy" role="status">Working…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status">{{note}}</p><button v-if="!data&&!busy" class="button subtle" @click="run(load)">Retry loading administration</button><OwnerAccess v-if="tab==='Admin access'"/><FinanceOperations v-else-if="tab==='Commerce'" control/><Subscription v-else-if="tab==='Billing'" control-plane/>
<template v-else-if="data && !['Platform guide','Audit log'].includes(tab)"><button class="button subtle" :disabled="busy" @click="run(load)">Refresh</button><label v-if="['Organizations','Plans','Site policies','Provisioning'].includes(tab)">Audit reason<input v-model="reason" maxlength="1000" placeholder="Required for changes"></label>
<template v-if="tab==='Organizations'"><p>{{data.counts.registered}} registered · {{data.counts.enabled}} enabled · {{data.counts.disabled}} disabled</p><form class="panel" @submit.prevent="action('register',form)"><h2>Register a separately hosted institute</h2><p>This creates an organization record and a setup job. It does not create a public-campus institute or make its website available. Server setup is a separate step.</p><div class="grid"><label>Name<input v-model="form.title" required maxlength="120"></label><label>Institute code<input v-model="form.code" required minlength="2" maxlength="12" pattern="[A-Za-z][A-Za-z0-9]{1,11}" title="Use 2–12 letters or numbers, starting with a letter" placeholder="ABCS"><small>Start with a letter, then letters or numbers. For example: ABCS or A1234.</small></label><label>Dedicated website address<input v-model="form.site_hostname" required placeholder="academy.sisuacademylk.com"><small>Domain name only, without https:// or a path. You must control this domain.</small></label><label>Billing/admin email<input type="email" v-model="form.admin_contact" required></label></div><button class="button primary" :disabled="busy">Create institute setup request</button></form>
<div class="scroll"><table><thead><tr><th>Organization</th><th>Host / code</th><th>Subscription</th><th>Provisioning</th><th>Manage</th></tr></thead><tbody><tr v-for="o in data.organizations" :key="o.name"><td>{{o.title}}<small>{{o.name}} · {{o.admin_contact}}</small></td><td>{{o.site_hostname}} · {{o.institute_code}}<p>{{o.custom_domain||'No custom domain'}}</p></td><td>{{o.plan}} · {{o.subscription?.state}}<p>Ends {{o.subscription?.ends_at||'—'}}</p></td><td>{{o.provisioning_state}} · {{o.enabled?'Enabled':'Suspended'}}</td><td><button class="button subtle" :disabled="busy" @click="choose(o)">Manage</button></td></tr></tbody></table></div><button class="button subtle" :disabled="busy||!page" @click="page--;run(load)">Previous organizations</button><button class="button subtle" :disabled="busy||data.organizations.length<50" @click="page++;run(load)">Next organizations</button><p v-if="!data.organizations.length">No organizations registered.</p>
<article v-if="tenant" class="panel"><h2>{{tenant}}</h2><button class="button subtle" :disabled="busy" @click="tenant='';manifest=null">Close organization</button><label>Custom domain metadata<input v-model="domain" placeholder="learning.customer.example"></label><button class="button subtle" :disabled="busy||!reason.trim()" @click="action('update_organization',{tenant,enabled:true,custom_domain:domain,reason})">Enable / save domain</button><button class="button subtle" :disabled="busy||!reason.trim()" @click="action('update_organization',{tenant,enabled:false,reason})">Suspend organization</button><button class="button subtle" :disabled="busy" @click="action('invite_billing_contact',{tenant})">Send billing invitation</button><label>Subscription state<select v-model="state"><option v-for="s in ['grace','past_due','suspended','cancelled','expired']">{{s}}</option></select></label><label v-if="state==='grace'">Grace until<input v-model="grace" type="datetime-local"></label><button class="button subtle" :disabled="busy||!reason.trim()" @click="action('subscription_state',{tenant,state,reason,grace_until:grace||null})">Save subscription state</button><button class="button subtle" :disabled="busy||!reason.trim()" @click="action('reactivate',{tenant,reason})">Restore eligible settled subscription</button><label>One-time trial days<input type="number" min="1" max="30" v-model.number="days"></label><button class="button subtle" :disabled="busy||!reason.trim()" @click="action('trial',{tenant,days,reason})">Grant eligible trial</button><section class="panel" v-if="commercial"><h3>Premium monthly offer</h3><p>{{commercial.offer.available?'Offer configured':commercial.offer.message}}</p><form @submit.prevent="saveOffer"><label>Monthly price in LKR minor units<input type="number" min="1" step="1" v-model.number="monthlyPrice" required></label><label><input type="checkbox" v-model="priceEnabled">Offer enabled</label><button class="button subtle" :disabled="busy||reason.trim().length<3">Save monthly offer</button></form><h3>Policy delivery</h3><p>{{commercial.policy_delivery?.status||'No delivery recorded'}} · revision {{commercial.policy_delivery?.revision||'—'}}</p><h3>Receipts</h3><p v-if="!commercial.receipts.length">No settled receipts.</p><p v-for="receipt in commercial.receipts" :key="receipt.name">{{receipt.name}} · {{receipt.currency}} {{(receipt.amount_minor/100).toFixed(2)}} · {{receipt.paid_at}}</p></section><details><summary>Custom policy overrides</summary><p>Use features, limits and support_tier. Empty objects inherit the subscription defaults.</p><label>Overrides JSON<textarea v-model="override" rows="8" spellcheck="false"/></label><button class="button subtle" :disabled="busy||!reason.trim()" @click="saveOverrides">Save overrides</button></details><div class="panel"><h3>Signed policy delivery</h3><p>Requires an operator-configured signing key. Generating a policy does not apply it to the institute.</p><button class="button subtle" :disabled="busy" @click="exportManifest">Generate signed policy</button><button v-if="manifest" class="button subtle" @click="downloadManifest">Download signed policy</button></div><p>Paid activation requires verified settlement. Suspension/reactivation and overrides need signed-manifest delivery by the operator.</p></article></template>
<template v-else-if="tab==='Plans'"><h2>Provider packages</h2><p>Individual, Silver, Gold and Platinum. This editor changes the catalogue on this platform site only. The public LMS has its own catalogue; these edits are not synchronized to it.</p><PlanEditor/></template><template v-else-if="tab==='Site policies'"><h2>Legacy isolated-site policies</h2><p>These technical policies apply to separately hosted institutes. They are not the Individual, Silver, Gold or Platinum provider packages.</p><button v-for="p in data.plans" class="button subtle" @click="editPlan(p)">{{p.name}}</button><form v-if="edit" class="panel" @submit.prevent="savePlan"><h2>{{edit.plan}}</h2><label>Price (LKR minor units)<input type="number" min="0" v-model.number="edit.price_minor" required></label><label>Period days<input type="number" min="1" max="366" v-model.number="edit.period_days" required></label><div class="grid"><div><label v-for="k in data.feature_keys" class="check"><input type="checkbox" v-model="edit.features[k]">{{k}}</label></div><div><label v-for="k in data.limit_keys">{{k}}<input type="number" min="0" step="1" v-model.number="edit.limits[k]"></label></div></div><p>Zero denies allocation. CUSTOM commercial pricing uses the assigned contract; support tier is an audited custom override.</p><button class="button primary" :disabled="busy||!reason.trim()">Save plan revision</button></form></template>
<template v-else-if="tab==='Provisioning'"><p>Infrastructure operators create the isolated Bench site/database, install apps, initialize the organization, deliver policy and enable DNS. This UI records progress; it does not create servers.</p><article v-for="j in data.jobs" :key="j.name" class="panel"><h2>{{j.organization}}</h2><p>{{j.name}} · {{j.status}} · {{j.modified}}</p><p>{{j.detail}}</p><button class="button subtle" :disabled="busy" @click="run(async()=>spec=await request('platform','provisioning_spec',{job:j.name},'GET'))">Inspect provisioning spec</button><p>Next: {{j.status==='ready'?'Verify signed manifest, invitation, DNS/TLS and smoke tests.':'Operator: inspect provisioning spec and execute the documented isolated-site workflow.'}}</p><button v-for="s in ['running','ready','failed']" class="button subtle" :disabled="busy||!reason.trim()" @click="action('provisioning_result',{job:j.name,status:s,reason})">Record {{s}}</button></article><pre v-if="spec">{{spec}}</pre><p v-if="!data.jobs.length">No provisioning jobs.</p></template>
<template v-else-if="tab==='Readiness'"><button class="button primary" :disabled="busy" @click="run(async()=>health=await request('health','readiness',{},'GET'))">Check local readiness</button><section v-if="health" class="panel"><h2>{{health.ready?'Local checks passed':'Local checks need attention'}}</h2><p v-for="(ok,name) in health.checks" :key="name">{{ok?'Pass':'Needs attention'}} · {{name}}</p><h3>Service configuration</h3><p v-for="(ok,name) in health.provider_configured" :key="name">{{name}} · {{ok?'Configured; delivery still needs testing':'Not configured'}}</p><p>{{health.note}}</p></section><p>Provider configuration is not provider acceptance. Complete the staging checklist before release.</p></template></template><section v-if="tab==='Audit log'"><h2>Control-plane audit history</h2><button class="button subtle" :disabled="busy" @click="run(loadAudit)">Refresh audit history</button><article v-for="row in auditRows" :key="row.name" class="panel"><h3>{{row.action}}</h3><p>{{row.creation}} · {{row.actor}} · {{row.reference}}</p><p>{{row.details}}</p></article><p v-if="!busy&&!auditRows.length">No audit entries on this page.</p><button class="button subtle" :disabled="busy||!auditPage" @click="auditPage--;run(loadAudit)">Previous audit entries</button><button class="button subtle" :disabled="busy||auditRows.length<50" @click="auditPage++;run(loadAudit)">Next audit entries</button></section></main></template>

<style scoped>.panel>.button{margin:8px 8px 8px 0}textarea{display:block;width:100%;max-width:100%;box-sizing:border-box}pre{overflow:auto;max-width:100%}.scroll{overflow:auto}label{display:block;margin:12px 0}input,select{max-width:100%;box-sizing:border-box}nav{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}nav .button{width:auto}nav button[aria-pressed="true"]{background:#54218a;color:white}.release{max-width:1200px;margin:auto;padding:32px 24px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.grid label{display:flex;flex-direction:column;gap:8px}.grid input{width:100%;padding:12px}small{display:block;line-height:1.5;color:#645a75}.release>h1{margin-bottom:12px}@media(max-width:700px){.grid{grid-template-columns:1fr}} </style>
